+    private void cancelPostponedNavigation(UI ui) {
+        ui.getInternals().clearLastHandledNavigation();
+        ui.getInternals().getWrapperElement().executeJs("this.serverConnected && this.serverConnected($0)", true);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasInput()) {
+            return;
+        }
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.add("What you have typed will be lost.");
+        dialog.setCloseOnOutsideClick(false);
+        Runnable keepEditing = () -> {
+            dialog.close();
+            getUI().ifPresent(this::cancelPostponedNavigation);
+        };
+        dialog.addDialogCloseActionListener(e -> keepEditing.run());
+        Button keep = new Button("Keep editing", e -> keepEditing.run());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.ERROR);
+        dialog.getFooter().add(keep, discard);
+        dialog.open();
+    }
+}
