+        assertEquals("", page.getByLabel("Name").inputValue());
+        page.locator("vaadin-grid").getByText("Hi there").first().waitFor();
+        page.getByLabel("Phone").fill("1");
+        assertTrue(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).isEnabled());
